// Parliamentary Procedure Practice Test 3. Original questions written for Valus from the HOSA 2026–27
// test plan (National Association of Parliamentarians topics), slightly harder than the sample items:
// applying Robert’s Rules to meeting situations, vote thresholds and motion characteristics.
import {q, mix} from './q.js';
const RONR='Robert’s Rules of Order Newly Revised', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const WHY='Why Have Rules', MEET='What Happens at a Meeting?', MOT='Handling Motions', DEB='Debate', AMD='Amendments', POST='Postponing and Referring to a Committee', MIND='How a Group Can Change Its Mind', VOTE='Voting and Elections', BYL='Bylaws and Other Rules and How to Use Them', ENF='How Rules are Enforced and Suspended', TABLE='Table of Rules', OFF='Officers, Committee Chairman, or Member';

export default {
 id:'parliamentary-procedure-3',
 event:'Parliamentary Procedure',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Robert’s Rules of Order Newly Revised, RONR In Brief and NAP study questions',
 plan:[{area:'National Association of Parliamentarians',weight:100,topics:[WHY,MEET,MOT,DEB,AMD,POST,MIND,VOTE,BYL,ENF,TABLE,OFF]}],
 questions:mix([
  q(WHY,'At a mass meeting called by sponsors to form a new group, what is the quorum?','Whoever attends the meeting',['A majority of those invited to attend','Two-thirds of the sponsors who called it','Twelve members, as in a small board'],'A','A mass meeting has no defined membership, so under RONR its quorum is simply the number of people who attend.',RONR),
  q(WHY,'Unless the assembly sets another number, what is the quorum of a committee?','A majority of the committee’s members',['Any two members of the committee','The committee chair plus one member','One-third of the committee’s members'],'B','A committee or board that has a set number of members needs a majority of them present to do business unless a different quorum is set.',RONR),
  q(WHY,'Midway through a meeting, members leave and the quorum is lost, but the group keeps voting. What is the status of motions adopted afterward?','They are null and void once the lack of quorum is established',['They stand, because no one objected when they were adopted','They stand if a majority of those still present agreed','They are valid until rescinded at the next regular meeting'],'C','Business transacted without a quorum is null and void. The chair should announce the loss of quorum, and only actions such as adjourning or recessing may follow.',RONR),
  q(WHY,'Which list names basic rights of every member of an assembly?','To attend, make motions, speak in debate and vote',['To preside, appoint committees and sign checks','To veto motions, close debate and set the agenda','To review the minutes before others and speak first'],'D','Each member has equal rights to attend meetings, make motions, speak in debate and vote; officers’ added duties come from the bylaws and RONR.',BRIEF),
  q(MEET,'In the standard order of business, special orders come immediately before which heading?','Unfinished business and general orders',['Reports of standing committees','Reading and approval of the minutes','Reports of officers and boards'],'A','The order is minutes, reports of officers, boards and standing committees, reports of special committees, special orders, unfinished business and general orders, then new business.',RONR),
  q(MEET,'Which words does a chair typically use to open a meeting?','“The meeting will come to order.”',['“I move that the meeting begin now.”','“Is there a second to start the meeting?”','“All in favor of starting, say aye.”'],'B','The chair calls the meeting to order at the scheduled time once a quorum is present; no motion or vote is needed to begin.',BRIEF),
  q(MEET,'After an agenda has been adopted, how can the assembly change it?','By a two-thirds vote or general consent',['Only by the chair’s decision alone','By a simple majority without notice','It cannot be changed during the meeting'],'C','Once adopted, an agenda can be changed only by a two-thirds vote, a majority of the entire membership or general consent.',RONR),
  q(MEET,'What does the term “orders of the day” refer to?','The program or agenda set for the meeting',['The minutes approved at the last meeting','The motions that are ruled out of order','The officers’ reports for the year'],'D','Orders of the day are the items scheduled for a meeting; a member may call for the orders of the day when the agenda is not being followed.',RONR),
  q(MOT,'A long, formal main motion written out in advance and beginning “Resolved, That…” is called what?','A resolution',['A point of order','A standing rule','A special report'],'A','A resolution is a main motion formally written and offered in writing; its operative clause begins “Resolved, That.”',RONR),
  q(MOT,'The chair has stated the question on a motion. Can the maker now withdraw it freely?','No; it now belongs to the assembly, which must permit it',['Yes; the maker may withdraw it at any time at all','No; a stated motion can never be withdrawn by anyone','Yes; but only if the seconder agrees to it first'],'B','Before the chair states it, the maker may withdraw or modify a motion freely; afterward it belongs to the assembly, and withdrawal needs general consent or a majority vote.',RONR),
  q(MOT,'A member moves to take an action that conflicts with the organization’s bylaws. What should the chair do?','Rule the motion out of order',['Put it to a two-thirds vote','Refer it to a committee first','Allow it if it gets a second'],'C','A main motion that conflicts with the bylaws, the corporate charter or law is out of order, and the chair should rule it so even if it is seconded.',RONR),
  q(MOT,'A member makes a motion in a way intended only to obstruct and delay the meeting. How should the chair treat it?','As dilatory, and decline to recognize it',['As privileged, so it must be voted on first','As a main motion that needs a two-thirds vote','As an appeal that must be put to the assembly'],'D','Motions used to obstruct business are dilatory; the chair should not recognize them, protecting the assembly’s right to transact business.',RONR),
  q(DEB,'May the maker of a motion speak against it in debate?','No, though the maker may vote against it',['Yes, at any time during the debate','No, and the maker may not vote on it','Yes, but only after all others speak'],'A','The maker of a motion may not speak against their own motion, although they may vote against it and may withdraw it with permission.',RONR),
  q(DEB,'Two members seek the floor. One has already spoken on the question; the other has not. Who is preferred?','The member who has not yet spoken',['The member who has already spoken','The member nearest the microphone','Whichever member the secretary chooses'],'B','A member who has not spoken on the pending question has preference over one who has, so that debate is shared fairly.',RONR),
  q(DEB,'A member wants to ask the speaker a question during debate. How should it be done?','Address the chair and ask if the speaker will yield',['Interrupt the speaker directly with the question','Wait and ask the speaker privately after the vote','Raise a point of order to ask the question'],'C','All remarks go through the chair. The member asks the chair whether the speaker will yield for a question, and the time used comes from the speaker’s time.',RONR),
  q(DEB,'During debate on a motion to buy a printer, a member starts discussing next year’s banquet. What rule applies?','Debate must be germane to the pending question',['Any topic may be raised once the floor is held','Unrelated topics need only a second to continue','The chair must allow it if time remains to speak'],'D','Debate must relate to the immediately pending question; the chair should call a speaker to order who strays from it.',BRIEF),
  q(AMD,'An amendment to a main motion has just been adopted. What happens next?','The main motion, as amended, is open and still needs a vote',['The main motion is adopted along with the amendment','The meeting moves on to the next item of business','The amendment must be voted on a second time'],'A','Adopting an amendment only changes the wording; the main motion as amended remains pending and must be voted on separately.',BRIEF),
  q(AMD,'A member offers a “friendly amendment,” and the maker of the motion accepts it. Is it adopted?','Only if the assembly adopts it by vote or general consent',['Yes, because the maker’s approval adopts it','Yes, because friendly amendments need no vote','No, because friendly amendments are not allowed'],'B','Once a motion is stated, it belongs to the assembly; any amendment, “friendly” or not, needs the assembly’s vote or general consent.',RONR),
  q(AMD,'An amendment is germane but works against the original intent of the motion. Is it in order?','Yes, if it is germane and is not simply a negation',['No, amendments must agree with the maker’s intent','No, it must be referred to a committee first','Yes, but only if the maker of the motion approves'],'C','An amendment may be hostile to the spirit of a motion and still be in order, as long as it is germane and does not merely turn the motion into its negative.',RONR),
  q(AMD,'A motion reads “to buy six chairs.” A member moves to strike “six” and insert “ten.” What form is this?','Strike out and insert',['Insert or add','Substitute','Division of the question'],'D','Strike out and insert removes words and puts others in their place; substitute replaces an entire paragraph or motion.',BRIEF),
  q(POST,'What is the latest time to which a motion may be postponed with the motion to postpone to a certain time?','No later than the end of the next regular session',['Any date the assembly chooses, even years later','No later than the end of the same meeting','Only to the following calendar year'],'A','A question cannot be postponed beyond the end of the next regular session, so that one session cannot bind the future indefinitely.',RONR),
  q(POST,'A member moves to postpone a motion to the next meeting and make it a special order. What vote is required?','Two-thirds, because a special order can override other business',['A majority, like any other motion to postpone','No vote, because the chair alone sets special orders','Unanimous consent of all members who are present'],'B','Making a postponed question a special order can interrupt other business, so it requires a two-thirds vote.',RONR),
  q(POST,'A special committee was appointed to plan one event. When does it cease to exist?','When it gives its final report on that task',['At the end of the organization’s fiscal year','Only when the bylaws are amended to end it','When its chair resigns from the organization'],'C','A special (ad hoc) committee is formed for a specific task and ceases to exist when it reports on that task; standing committees continue.',RONR),
  q(POST,'While a motion to postpone indefinitely is pending, may members debate the merits of the main motion?','Yes, because it opens the main question to debate',['No, because it is not debatable at all','No, debate is limited to postponing alone','Yes, but only the maker of the main motion'],'D','Postpone indefinitely is debatable, and its debate goes into the merits of the main question, since adopting it would kill the main motion.',RONR),
  q(MIND,'What is the immediate effect of a member making a motion to reconsider an adopted motion?','Action on the adopted motion is suspended until reconsider is decided',['The adopted motion is cancelled at once and cannot return','The original vote is automatically repeated by ballot','The adopted motion becomes a special order for next meeting'],'A','Making the motion to reconsider suspends action under the original vote until the reconsideration is dealt with or the time limit expires.',RONR),
  q(MIND,'In a convention lasting several days, when may the motion to reconsider be made?','On the same day the vote was taken or the next business day',['Any day during the following year’s convention','Only within the same hour that the vote was taken','Only on the final day of the convention, before adjournment'],'B','In a session of several days, reconsider can be moved on the day of the vote or on the next day on which a business meeting is held.',RONR),
  q(MIND,'A main motion was defeated at last month’s meeting. Can it be made again at this month’s meeting?','Yes; it can be renewed at a later session',['No; a defeated motion can never return','Only if the original maker agrees','Only by a motion to rescind the vote'],'C','A motion that failed cannot be renewed in the same session, but it may be introduced again at any later session.',RONR),
  q(MIND,'Officers took emergency action without authority, and the assembly now wants to approve it. Which motion applies?','Ratify',['Rescind','Reconsider','Discharge'],'D','Ratify (or confirm) is a main motion approving action already taken on the group’s behalf without proper authority, as long as the assembly could have authorized it.',RONR),
  q(VOTE,'A member who cannot attend wants a friend to vote on their behalf. Is proxy voting allowed under RONR?','No, unless the bylaws or law permit it',['Yes, if the friend is also a member','Yes, if the chair approves it first','No, unless the vote is a voice vote'],'A','Proxy voting conflicts with the idea that only those present and taking part may vote; it is not allowed unless the bylaws or governing law permit it.',RONR),
  q(VOTE,'With 100 members present, a rule requires a majority of members present. The vote is 45 yes and 40 no. What is the result?','Lost, because 51 yes votes were needed',['Adopted, because yes outnumbers no','Adopted, because 45 is over 40 percent','Tied, because 15 members did not vote'],'B','A majority of members present means more than half of the 100 present, or 51, so abstentions count against the motion under this rule.',RONR),
  q(VOTE,'A motion requiring a majority vote ends in a tie. What is the result?','The motion is lost',['The chair must break the tie','The vote is taken again at once','The motion is adopted'],'C','A tie is not a majority, so the motion is lost; if the chair is a member, the chair may vote to break or create a tie.',BRIEF),
  q(VOTE,'In which situation is a roll call vote most useful?','When members are accountable to constituents and votes must be recorded',['When the assembly wants every vote to stay completely secret','When the chair is unsure of a voice vote in a small meeting','When no member objects, so no vote is needed'],'D','A roll call records how each member votes, which suits representative bodies whose members answer to constituents; ballots are used for secrecy.',RONR),
  q(VOTE,'The chair asks for general consent, and one member objects. What happens?','The question is put to a formal vote',['The action is taken anyway','The member must leave the room','The question is dropped for the session'],'A','General consent works only if no member objects; a single objection means the chair must take a formal vote.',BRIEF),
  q(BYL,'A new organization is adopting its first bylaws. What vote is required?','A majority vote',['A two-thirds vote','A unanimous vote','A three-fourths vote'],'B','Initial bylaws are adopted by majority vote, but once in effect they are usually amended only with previous notice and a two-thirds vote.',RONR),
  q(BYL,'What vote adopts a new standing rule?','A majority vote, without previous notice',['Two-thirds with previous notice','Unanimous consent of the board','Approval by the parliamentarian and chair'],'C','Standing rules deal with administrative matters and can be adopted by majority vote without notice, ranking below the parliamentary authority.',RONR),
  q(BYL,'What vote adopts a special rule of order?','Previous notice and two-thirds, or a majority of the entire membership',['A majority vote at any meeting, without notice','The chair’s ruling, subject to an appeal by any two members','A plurality of the votes cast at the annual meeting that day'],'D','Special rules of order supersede the parliamentary authority, so they require previous notice and a two-thirds vote or a majority of the entire membership.',RONR),
  q(BYL,'An incorporated society’s bylaws conflict with its corporate charter. Which one governs?','The corporate charter',['The bylaws, since members adopted them','Whichever was adopted most recently','The standing rules, as a tiebreaker'],'B','The corporate charter ranks above the bylaws and below applicable law; a bylaw that conflicts with the charter has no effect.',RONR),
  q(ENF,'A member keeps speaking out of turn after a warning. What step may the chair take next?','“Name” the member, starting disciplinary action',['Expel the member immediately without a vote','Fine the member for each interruption','Hand the gavel to the disruptive member'],'A','If a member continues to disrupt after being called to order, the chair may “name” the offender; the assembly then decides on any penalty.',RONR),
  q(ENF,'A point of order is raised, and the chair is unsure how to rule. What may the chair do?','Submit the question to the assembly for a vote',['Ignore the point until the next meeting','Ask the maker to withdraw the point','Adjourn the meeting immediately'],'B','The chair may consult the parliamentarian or, when in doubt, put the point of order to the assembly for decision.',RONR),
  q(ENF,'A nonmember visitor disrupts a meeting. Who may have the visitor removed?','The chair, without a vote',['Only the full membership by two-thirds','Only a court order from a judge','The visitor’s sponsoring member'],'C','Nonmembers attend at the assembly’s pleasure; the chair may have a disorderly nonmember removed without a vote of the assembly.',RONR),
  q(ENF,'Members meeting in executive session discuss confidential matters. What duty applies afterward?','Keep the proceedings secret',['Post a summary online','Share it with all guests','Read it at the next meeting'],'D','Proceedings of an executive session are secret; a member who discloses them may be subject to discipline.',RONR),
  q(TABLE,'Which subsidiary motion is both debatable and amendable?','Commit or refer',['Lay on the table','Previous question','Postpone indefinitely, with amendments'],'A','Commit is debatable (on whether to commit) and amendable (as to committee, instructions and timing); lay on the table and previous question are neither.',RONR),
  q(TABLE,'A member calls for a division of the assembly. What is required?','No second and no vote; one member’s demand is enough',['A second and a majority vote of the assembly','A second and a two-thirds vote of those present','The chair’s approval and a second from another member'],'B','Division of the assembly may be demanded by a single member without a second or vote, and the chair must retake the vote as a rising vote.',RONR),
  q(TABLE,'When must an objection to the consideration of a question be raised, and what vote sustains it?','Before debate begins; two-thirds against consideration',['At any time; a majority in favor','After the vote; a tie sustains it','Before debate begins; a majority in favor of the objection'],'C','Objection to consideration must be raised before debate or any subsidiary motion is stated; consideration is blocked if two-thirds vote against it.',RONR),
  q(TABLE,'Does a parliamentary inquiry need a second?','No, and it is answered by the chair',['Yes, and it is decided by a vote','Yes, and it may be debated','No, but it needs a vote'],'D','A parliamentary inquiry asks the chair for an opinion on procedure; it needs no second, is not debatable and is not voted on.',RONR),
  q(TABLE,'Which of these motions requires a majority vote?','Lay on the table',['Previous question','Suspend the rules','Objection to consideration'],'A','Lay on the table needs a majority; previous question and suspend the rules need two-thirds, and objection to consideration needs two-thirds against.',RONR),
  q(OFF,'If the parliamentarian is a member of the assembly, when should they vote?','Only by ballot, to stay impartial',['On every motion, like other members','Only to break ties on voice votes','Never, under any circumstances'],'B','To protect their impartiality, a parliamentarian who is a member gives up the right to vote except on a ballot vote.',RONR),
  q(OFF,'Both the president and vice-president are absent. Who presides?','A chair pro tem elected by the assembly',['The secretary, automatically','The member who arrived at the meeting first','The treasurer, by long-standing tradition'],'C','In the absence of both, the secretary calls the meeting to order and the assembly elects a chair pro tem to preside for that meeting.',RONR),
  q(OFF,'What is the treasurer’s main duty?','To be custodian of the organization’s funds',['To keep the minutes of each meeting','To rule on points of order','To preside when the president leaves'],'D','The treasurer receives, holds and pays out funds as authorized and reports on finances; the secretary keeps the minutes.',RONR),
  q(OFF,'The secretary is absent. Who takes the minutes?','A secretary pro tem chosen at the meeting',['No one; minutes are skipped that day','The president, while still presiding','The parliamentarian, automatically'],'A','When the secretary is absent, a secretary pro tem is appointed or elected for that meeting so that the record is kept.',RONR)
 ],7943)
};
